    static func closeQuestion(count: Int, preview: Bool, wrote: Bool) -> String {
        switch (min(count, 2) == 2 ? -1 : count, preview, wrote) {
        case (0, false, false): "You picked 0 answers. Closing will discard them."
        case (0, false, true): "You wrote a reply. Closing will discard it."
        case (0, true, false): "You changed 0 settings. Closing will discard them."
