    static func revisedLine(time: String, added: Int, removed: Int, rewritten: Bool) -> String {
        if rewritten { return "Rewritten \(time)" }
        return switch (min(added, 2) == 2 ? -1 : added, min(removed, 2) == 2 ? -1 : removed) {
        case (0, 0): "Revised \(time)"
        case (0, 1): "Revised \(time) · 1 part removed"
        case (0, -1): "Revised \(time) · \(removed) parts removed"
        case (1, 0): "Revised \(time) · 1 part new"
        case (1, 1): "Revised \(time) · 1 part new · 1 removed"
        case (1, -1): "Revised \(time) · 1 part new · \(removed) removed"
        case (-1, 0): "Revised \(time) · \(added) parts new"
        case (-1, 1): "Revised \(time) · \(added) parts new · 1 removed"
        case (-1, -1): "Revised \(time) · \(added) parts new · \(removed) removed"
        default: ""
